import type { LookupOptions, LookupValue } from "./lookup-model";

// Relative on purpose: the shadcn CLI rewrites import paths, never augmentation module names.
declare module "../data-grid/types" {
  interface GridCellTypes {
    // `any` lets a column pass `LookupOptions<Row>`
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    lookup: { value: LookupValue; options: LookupOptions<any> };
  }
}

/** Public entry point — the only module consumers/docs should import from. */
export { lookupCellType } from "./lookup-cell-type";
export type { LookupFetchRequest, LookupLabels, LookupOption, LookupOptions, LookupValue } from "./lookup-model";

"use client";

import { CellSpan, type CellRenderProps, type CellType } from "@/registry/default/components/data-grid/data-grid";
import { createFilterMatcher } from "@/registry/default/components/data-grid/data-grid";
import type { FilterSpec } from "@/registry/default/components/data-grid/data-grid";
import { TEXT_FILTER_OPERATORS, sortCollator, UnparseableTextError } from "@/registry/default/components/data-grid/data-grid-sdk";
import { LookupEditor } from "./lookup-editor";
import { isUnresolved, MAX_LOOKUP_TEXT, readLookup, recallOption, rememberOption, type LookupOptions, type LookupValue } from "./lookup-model";

function LookupCell({ value, options }: CellRenderProps<unknown, LookupValue, LookupOptions>) {
  const option = readLookup(value);
  if (!option) return <CellSpan text="" />;
  // a shown label pastes back to its key, also from outside the grid
  if (options?.fetchOptions && !isUnresolved(value)) rememberOption(options.fetchOptions, option);
  if (isUnresolved(value)) {
    return (
      <span data-unresolved="" className="block w-full truncate text-muted-foreground">
        <bdi>{option.label}</bdi>
      </span>
    );
  }
  return <CellSpan text={option.label} />;
}

const matchers = new WeakMap<FilterSpec, (text: string) => boolean>();

function matcherFor(filter: FilterSpec): (text: string) => boolean {
  let matcher = matchers.get(filter);
  if (!matcher) {
    matcher = createFilterMatcher(filter);
    matchers.set(filter, matcher);
  }
  return matcher;
}

function labelOf(value: unknown): string {
  return readLookup(value)?.label ?? "";
}

/**
 * `lookup`: the stored value is `{ value, label }` (the key and the text the user sees). `toText`
 * copies the label; `fromText` resolves a pasted label or key against the options the editor
 * listed, a cell showed, or `toText` wrote (copy, export, print, fill source, autosize, filter value list), else follows `unresolvedPaste`. Sort, quick search, and the text filter operators
 * read the label.
 */
export const lookupCellType: CellType<unknown, LookupValue, LookupOptions> = {
  Cell: LookupCell,
  Editor: LookupEditor,
  toText: (value, options) => {
    const option = readLookup(value);
    if (!option) return "";
    if (options?.fetchOptions && !isUnresolved(value)) rememberOption(options.fetchOptions, option);
    return option.label;
  },
  fromText: (text, options) => {
    const trimmed = text.trim().slice(0, MAX_LOOKUP_TEXT);
    if (trimmed === "") return null;
    const hit = options?.fetchOptions ? recallOption(options.fetchOptions, trimmed) : undefined;
    if (hit) return hit;
    if (options?.unresolvedPaste === "keep") return { value: trimmed, label: "" };
    if (options?.unresolvedPaste === "clear") return null;
    throw new UnparseableTextError("no known option");
  },
  clearValue: () => null,
  isEmpty: (value) => readLookup(value) === null,
  compare: (a, b) => sortCollator().compare(labelOf(a), labelOf(b)),
  toSearchText: (value) => labelOf(value),
  filter: {
    operators: TEXT_FILTER_OPERATORS,
    match: (value, filter) => matcherFor(filter)(labelOf(value)),
  },
  align: "start",
};

"use client";

import { useEffect, useId, useLayoutEffect, useRef, useState, type KeyboardEvent } from "react";
import { cn } from "@/lib/utils";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { useDebouncedInput } from "@/registry/default/components/gridcn/use-debounce";
import { useCommitGuard, type CellEditorProps } from "@/registry/default/components/data-grid/data-grid";
import { columnLabelText, deepMergeLabels, isComposingKey, isDev, useDataGridInputDebounce } from "@/registry/default/components/data-grid/data-grid-sdk";
import {
  DEFAULT_LABELS,
  MAX_LOOKUP_TEXT,
  readLookup,
  rememberOption,
  sanitizeOptions,
  type LookupOption,
  type LookupOptions,
  type LookupValue,
} from "./lookup-model";

type Fetched = { status: "idle" | "loading" | "ready" | "error"; options: readonly LookupOption[] };

/** Opens on edit start. Typing searches `fetchOptions` after a pause; arrow keys move, Enter or a click picks, Escape cancels. */
export function LookupEditor(props: CellEditorProps<unknown, LookupValue, LookupOptions>) {
  const { value, options, onChange, commit, cancel, column, pending, rejectionCount, initialText, row, rowId } = props;
  const labels = deepMergeLabels(DEFAULT_LABELS, options?.labels);
  const minQueryLength = Math.max(0, options?.minQueryLength ?? 0);
  const providerDelay = useDataGridInputDebounce();
  const delayMs = options?.debounceMs ?? providerDelay;
  const listId = useId();
  const inputRef = useRef<HTMLInputElement>(null);
  const committed = useCommitGuard();
  const current = readLookup(value);

  const lastRejectionCount = useRef(rejectionCount ?? 0);
  useEffect(() => {
    if ((rejectionCount ?? 0) !== lastRejectionCount.current) committed.reset();
    lastRejectionCount.current = rejectionCount ?? 0;
  }, [rejectionCount, committed]);

  const [query, setQuery] = useState((initialText ?? "").slice(0, MAX_LOOKUP_TEXT));
  const input = useDebouncedInput(query, setQuery, { delayMs });
  const [fetched, setFetched] = useState<Fetched>({ status: "idle", options: [] });
  const [active, setActive] = useState(0);
  const [attempt, setAttempt] = useState(0);
  const latest = useRef(options);
  const target = useRef({ row, rowId, columnId: column.id });
  const warnedIdentity = useRef(false);
  useLayoutEffect(() => {
    const previous = latest.current?.fetchOptions;
    if (previous && options?.fetchOptions && previous !== options.fetchOptions && !warnedIdentity.current && isDev()) {
      warnedIdentity.current = true;
      console.warn(`[data-grid-lookup] fetchOptions of column "${column.id}" changed identity while the editor was open. Pasted labels resolve through a cache keyed on that function: define it outside the render or memoize it.`);
    }
    latest.current = options;
    target.current = { row, rowId, columnId: column.id };
  });

  useEffect(() => {
    const el = inputRef.current;
    if (!el) return;
    el.focus({ preventScroll: true });
    const end = el.value.length;
    el.setSelectionRange(end, end);
  }, []);

  useEffect(() => {
    const fetchOptions = latest.current?.fetchOptions;
    if (!fetchOptions || query.length < minQueryLength) {
      setFetched({ status: "idle", options: [] });
      return;
    }
    const controller = new AbortController();
    setFetched((prev) => ({ status: "loading", options: prev.options }));
    new Promise<unknown>((resolve) => resolve(fetchOptions({ query, signal: controller.signal, ...target.current })))
      .then((answer) => {
        if (controller.signal.aborted) return;
        const list = sanitizeOptions(answer, latest.current?.maxResults);
        for (const option of list) rememberOption(fetchOptions, option);
        setFetched({ status: "ready", options: list });
        setActive(0);
      })
      .catch(() => {
        if (controller.signal.aborted) return;
        setFetched((prev) => ({ status: "error", options: prev.options }));
      });
    return () => controller.abort();
  }, [query, minQueryLength, attempt]);

  const pick = (option: LookupOption) => {
    if (!committed.tryCommit()) return;
    onChange(option);
    commit({ dx: 0, dy: 0 });
  };

  const typingPending = input.inputValue !== query;
  const list = fetched.options;
  const activeOption = list[Math.min(active, list.length - 1)];
  const optionId = (index: number) => `${listId}-${index}`;

  const onKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (isComposingKey(event)) return;
    if (event.key === "ArrowDown" || event.key === "ArrowUp") {
      event.preventDefault();
      if (list.length === 0) return;
      const step = event.key === "ArrowDown" ? 1 : -1;
      setActive((index) => (Math.min(index, list.length - 1) + step + list.length) % list.length);
      return;
    }
    if (event.key === "Enter") {
      event.preventDefault();
      if (typingPending) input.flush();
      else if (activeOption && fetched.status === "ready") pick(activeOption);
      return;
    }
    if (event.key === "Escape") {
      if (committed.tryCommit()) cancel();
      return;
    }
    input.inputProps.onKeyDown(event);
  };

  let statusText = "";
  if (query.length < minQueryLength) statusText = labels.typeMore(minQueryLength - query.length);
  else if (fetched.status === "loading") statusText = labels.searching;
  else if (fetched.status === "error") statusText = labels.error;
  else if (fetched.status === "ready" && list.length === 0) statusText = labels.noResults;

  return (
    <Popover
      open
      onOpenChange={(next, details) => {
        if (!next && details.reason === "escape-key" && isComposingKey(details.event)) {
          details.cancel();
          return;
        }
        if (!next && committed.tryCommit()) cancel();
      }}
    >
      <PopoverTrigger nativeButton={false} render={<span className="block w-full min-w-0 truncate" />}>
        {current?.label ?? ""}
      </PopoverTrigger>
      <PopoverContent data-grid-cell-editor="" align="start" className="w-64 gap-0 p-0 data-open:animate-none data-closed:animate-none">
        <div className="p-1.5">
          <Input
            ref={inputRef}
            {...input.inputProps}
            onKeyDown={onKeyDown}
            role="combobox"
            aria-expanded={list.length > 0}
            aria-autocomplete="list"
            aria-controls={listId}
            aria-activedescendant={activeOption ? optionId(Math.min(active, list.length - 1)) : undefined}
            aria-label={columnLabelText(column)}
            aria-busy={pending || fetched.status === "loading" || undefined}
            readOnly={pending}
            maxLength={MAX_LOOKUP_TEXT}
            dir="auto"
            placeholder={current?.label}
            className="h-8 w-full border-none bg-transparent px-2 shadow-none outline-none focus-visible:ring-0"
          />
        </div>
        <ul id={listId} role="listbox" aria-label={columnLabelText(column)} className={cn("max-h-60 overflow-auto p-1", list.length === 0 && "hidden")}>
          {list.map((option, index) => (
            <li
              key={option.value}
              id={optionId(index)}
              role="option"
              aria-selected={index === Math.min(active, list.length - 1)}
              data-active={index === Math.min(active, list.length - 1) ? "" : undefined}
              data-current={option.value === current?.value ? "" : undefined}
              className="cursor-default truncate rounded-md px-2 py-1.5 text-sm data-active:bg-accent data-active:text-accent-foreground data-current:font-medium"
              onPointerDown={(event) => event.preventDefault()}
              onPointerEnter={() => setActive(index)}
              onClick={() => pick(option)}
            >
              <bdi>{option.label}</bdi>
            </li>
          ))}
        </ul>
        <div role="status" aria-live="polite" className={cn("flex items-center justify-between gap-2 px-3 py-2 text-xs text-muted-foreground", statusText === "" && "sr-only")}>
          <span>{statusText}</span>
          {fetched.status === "error" && (
            <Button type="button" size="xs" variant="ghost" onClick={() => setAttempt((n) => n + 1)}>
              {labels.retry}
            </Button>
          )}
        </div>
      </PopoverContent>
    </Popover>
  );
}

import { toSafeText } from "@/registry/default/components/data-grid/data-grid-sdk";

/** One choice a server offers: `value` is the stored key, `label` the text the user sees. */
export type LookupOption = { value: string; label: string };

/** A lookup cell stores the picked option, or `null` when empty. A bare string is a key without a label (unresolved). */
export type LookupValue = LookupOption | string | null;

/** What `fetchOptions` receives. `TData` is the row type of the grid. */
export type LookupFetchRequest<TData = unknown> = {
  /** The text the user typed; `""` asks for the default list. */
  query: string;
  /** Aborted when the user types again, closes the editor, or the cell unmounts. */
  signal: AbortSignal;
  /** The row being edited, so a dependent lookup can narrow its options. The request does not repeat when a push changes the row during the edit. */
  row: TData;
  /** The id of the row being edited. */
  rowId: string;
  /** The id of the lookup column. */
  columnId: string;
};

/** Text the editor shows; each field falls back to English. */
export type LookupLabels = {
  searching: string;
  noResults: string;
  error: string;
  retry: string;
  /** Receives the missing character count. */
  typeMore: (missing: number) => string;
};

/** Column `options` of the `lookup` cell type. `TData` is the row type of the grid; it types `request.row`. */
export type LookupOptions<TData = unknown> = {
  /** Resolves the options that match `query`. The labels it lists, and the labels the cells show, paste back to their keys. */
  fetchOptions: (request: LookupFetchRequest<TData>) => Promise<readonly LookupOption[]>;
  /** Wait after the last keystroke before a request starts. Default: the grid's `inputDebounceMs`. */
  debounceMs?: number;
  /** Fewest typed characters that start a request. Default `0`: the default list loads on open. */
  minQueryLength?: number;
  /** Most options shown; extra options are dropped. Default `50`, at most `200`. */
  maxResults?: number;
  /** A pasted or imported text that matches no known option: `"reject"` keeps the cell value and reports the text to `onValidationError`, `"clear"` empties the cell, `"keep"` stores the trimmed text as `{ value: text, label: "" }`, shown as unresolved. Default `"reject"`. */
  unresolvedPaste?: "reject" | "clear" | "keep";
  labels?: Partial<LookupLabels>;
};

export const DEFAULT_MAX_RESULTS = 50;
export const MAX_RESULTS_LIMIT = 200;
export const MAX_LOOKUP_TEXT = 256;
const MAX_KNOWN_LABELS = 5000;

export const DEFAULT_LABELS: LookupLabels = {
  searching: "Searching…",
  noResults: "No results",
  error: "Could not load options",
  retry: "Retry",
  typeMore: (missing) => `Type ${missing} more character${missing === 1 ? "" : "s"}`,
};

function clip(text: string): string {
  return text.length > MAX_LOOKUP_TEXT ? text.slice(0, MAX_LOOKUP_TEXT) : text;
}

/** Reads any stored value as an option: a bare key stays visible as its own label (an unresolved value). */
export function readLookup(value: unknown): LookupOption | null {
  if (value == null) return null;
  if (typeof value === "object" && value !== null) {
    const raw = value as { value?: unknown; label?: unknown };
    if (typeof raw.value === "string" && raw.value !== "" && typeof raw.label === "string" && raw.label !== "" && raw.value.length <= MAX_LOOKUP_TEXT && raw.label.length <= MAX_LOOKUP_TEXT) {
      return value as LookupOption;
    }
  }
  if (typeof value === "string" || (typeof value === "number" && Number.isFinite(value))) {
    const text = clip(toSafeText(value));
    return text === "" ? null : { value: text, label: text };
  }
  if (typeof value !== "object") return null;
  const raw = value as { value?: unknown; label?: unknown };
  if (typeof raw.value !== "string" && !(typeof raw.value === "number" && Number.isFinite(raw.value))) return null;
  const key = clip(toSafeText(raw.value));
  if (key === "") return null;
  const label = typeof raw.label === "string" && raw.label !== "" ? clip(raw.label) : key;
  return { value: key, label };
}

/** True when the stored value carries no label of its own. */
export function isUnresolved(value: unknown): boolean {
  if (readLookup(value) === null) return false;
  if (typeof value !== "object" || value === null) return true;
  const label = (value as { label?: unknown }).label;
  return typeof label !== "string" || label === "";
}

/** Keeps at most `limit` well-formed options from an untrusted answer; the first of a repeated value wins. */
export function sanitizeOptions(answer: unknown, limit: number | undefined): LookupOption[] {
  if (!Array.isArray(answer)) throw new TypeError("fetchOptions must resolve an array of { value, label }");
  const max = Math.min(Math.max(1, Math.floor(limit ?? DEFAULT_MAX_RESULTS) || DEFAULT_MAX_RESULTS), MAX_RESULTS_LIMIT);
  const seen = new Set<string>();
  const out: LookupOption[] = [];
  for (const item of answer) {
    if (out.length >= max) break;
    if (typeof item !== "object" || item === null) continue;
    const { value, label } = item as { value?: unknown; label?: unknown };
    if ((typeof value !== "string" && !(typeof value === "number" && Number.isFinite(value))) || typeof label !== "string") continue;
    const key = clip(toSafeText(value));
    if (key === "") continue;
    if (seen.has(key)) continue;
    seen.add(key);
    out.push({ value: key, label: label === "" ? key : clip(label) });
  }
  return out;
}

type KnownOptions = { byLabel: Map<string, LookupOption | null>; byValue: Map<string, LookupOption> };
const known = new WeakMap<object, KnownOptions>();

function dropOldest<T>(map: Map<string, T>): void {
  if (map.size > MAX_KNOWN_LABELS) map.delete(map.keys().next().value as string);
}

/** Remembers an option so a copied label pastes back to its key. Bounded: the oldest entry leaves first. */
export function rememberOption(owner: object, option: LookupOption): void {
  let index = known.get(owner);
  if (!index) {
    index = { byLabel: new Map(), byValue: new Map() };
    known.set(owner, index);
  }
  const labelKey = option.label.toLowerCase();
  const same = index.byLabel.get(labelKey);
  index.byLabel.delete(labelKey);
  // a label shared by two keys is ambiguous and resolves to nothing
  index.byLabel.set(labelKey, same === null || (same && same.value !== option.value) ? null : option);
  index.byValue.delete(option.value);
  index.byValue.set(option.value, option);
  dropOldest(index.byLabel);
  dropOldest(index.byValue);
}

/** The remembered option whose label (case-insensitive) or key equals `text`. */
export function recallOption(owner: object, text: string): LookupOption | undefined {
  const index = known.get(owner);
  const byLabel = index?.byLabel.get(text.toLowerCase());
  return byLabel === null ? index?.byValue.get(text) : (byLabel ?? index?.byValue.get(text));
}
